func text(im *image.RGBA,x,y,scale int,s string,c color.RGBA){s=strings.NewReplacer("Ă","A","Â","A","Î","I","Ș","S","Ț","T").Replace(strings.ToUpper(s));for _,r:=range s{if r!=' '{g,ok:=glyphs[unicode.ToUpper(r)];if !ok{g=glyphs['?']};for j,bits:=range g{for i:=0;i<5;i++{if bits&(1<<uint(4-i))!=0{rect(im,x+i*scale,y+j*scale,scale,scale,c)}}}};x+=6*scale}}
func paragraph(im *image.RGBA,x,y,width,maxLines int,s string,c color.RGBA){columns:=width/12;if columns<1{return};row:=0;for _,line:=range strings.Split(s,"\n"){r:=[]rune(line);for len(r)>0{n:=len(r);if n>columns{n=columns};if row>=maxLines{return};text(im,x,y+row*24,2,string(r[:n]),c);row++;r=r[n:]};if len(line)==0{row++}}}
